function GlassColorantSievingClothMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassColorantSievingClothMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassColorantSievingClothMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassColorantSievingClothMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassColorantSievingClothMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassColorantSievingClothMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassColorantSievingClothMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassColorantSievingClothMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassColorantSievingClothMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassColorantSievingClothMaker.buildings==0 then return false,"Potrebna krpna delavnica" end; if not GlassColorantSievingClothMaker.maker then return false,"Potreben krpar" end; return true end
function GlassColorantSievingClothMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassColorantSievingClothMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassColorantSievingClothMaker.ironStock=GlassColorantSievingClothMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassColorantSievingClothMaker.bronzeStock=GlassColorantSievingClothMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassColorantSievingClothMaker.woodStock=GlassColorantSievingClothMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassColorantSievingClothMaker.leatherStock=GlassColorantSievingClothMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassColorantSievingClothMaker.silverStock=GlassColorantSievingClothMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassColorantSievingClothMaker.goldStock=GlassColorantSievingClothMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassColorantSievingClothMaker.jewelStock=GlassColorantSievingClothMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassColorantSievingClothMaker.pearlStock=GlassColorantSievingClothMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassColorantSievingClothMaker.maker then t=math.max(1,t-math.floor(GlassColorantSievingClothMaker.maker.skill/13)) end; table.insert(GlassColorantSievingClothMaker.activeMaking,{id="glasscolorantsievingcloth_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassColorantSievingClothMaker.completeMaking(m) local q=1.0+(GlassColorantSievingClothMaker.getQualityBonus()/100); if GlassColorantSievingClothMaker.maker then q=q+(GlassColorantSievingClothMaker.maker.skill/140) end; q=math.min(2.5,q); GlassColorantSievingClothMaker.productStock[m.productType]=(GlassColorantSievingClothMaker.productStock[m.productType] or 0)+m.quantity; GlassColorantSievingClothMaker.totalProducts=GlassColorantSievingClothMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassColorantSievingClothMaker.maker then GlassColorantSievingClothMaker.maker.itemsMade=GlassColorantSievingClothMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassColorantSievingClothMaker.maker.skill=math.min(100,GlassColorantSievingClothMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krupa izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasscolorantsievingcloth.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassColorantSievingClothMaker.update(dt) if not _G.state then return end; GlassColorantSievingClothMaker.dayTimer=GlassColorantSievingClothMaker.dayTimer+dt; if GlassColorantSievingClothMaker.dayTimer>=30 then GlassColorantSievingClothMaker.dayTimer=0; for i=#GlassColorantSievingClothMaker.activeMaking,1,-1 do local m=GlassColorantSievingClothMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassColorantSievingClothMaker.completeMaking(m); table.remove(GlassColorantSievingClothMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassColorantSievingClothMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassColorantSievingClothMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
